setup:
CREATE TABLE features AS SELECT * FROM (VALUES
  (1, ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))')),
  (2, ST_GeomFromText('POLYGON((0 0, 10 10, 10 0, 0 10, 0 0))')),
  (3, ST_GeomFromText('POLYGON((0 0, 5 0, 5 5, 0 5, 0 0))')),
  (4, ST_GeomFromText('POLYGON((0 0, 4 4, 4 0, 0 4, 0 0))'))
) t(feature_id, geom);

solution:
LOAD spatial;

SELECT feature_id,
       ST_IsValid(ST_MakeValid(geom)) AS fixable
FROM features
WHERE NOT ST_IsValid(geom)
ORDER BY feature_id;
